#!/usr/bin/env bash
set -e

PROJECT_NAME="stash-tracker"

echo "🌿 Creating Stash Tracker project..."
mkdir -p "$PROJECT_NAME"
cd "$PROJECT_NAME"

# 1. Create Next.js project
echo "📦 Scaffolding Next.js..."
npx create-next-app@latest . --typescript --tailwind --eslint --app --src-dir --import-alias "@/*" --use-npm --yes

# 2. Install additional dependencies
echo "📥 Installing dependencies..."
npm install prisma @prisma/client zustand @tanstack/react-query next-themes framer-motion sonner recharts date-fns lucide-react

# 3. Install dev dependencies
npm install -D @types/node

# 4. Initialize shadcn/ui
echo "🎨 Initializing shadcn/ui..."
npx shadcn@latest init -y --style new-york --base-color neutral

# 5. Add shadcn components
echo "🧩 Adding shadcn components..."
npx shadcn@latest add button input label card badge tabs switch select textarea separator progress sheet dialog dropdown-menu alert-dialog skeleton

# 6. Initialize Prisma
echo "🗄️ Setting up Prisma..."
npx prisma init --datasource-provider sqlite

# 7. Write all custom source files
echo "📝 Writing custom source files..."

# ── .env ──
cat << 'HEREDOC_EOF' > .env
DATABASE_URL=file:./dev.db
HEREDOC_EOF

echo "  setup.sh: Starting file writes..."

# ── prisma/schema.prisma ──
mkdir -p prisma
cat << 'HEREDOC_EOF' > prisma/schema.prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "sqlite"
  url      = env("DATABASE_URL")
}

model Product {
  id               String   @id @default(cuid())
  name             String
  strain           String   @default("")
  type             String   @default("hybrid")
  thc              Float    @default(0)
  cbd              Float    @default(0)
  amount           Float    @default(0)
  price            Float    @default(0)
  picture          String?
  notes            String?
  rating           Float    @default(0)
  brand            String?
  consumptionCount Int      @default(0)
  lastConsumed     DateTime?
  favorite         Boolean  @default(false)
  tags             String   @default("")
  effects          String   @default("")
  createdAt        DateTime @default(now())
  updatedAt        DateTime @updatedAt

  sessions         Session[]
  consumptionLogs  ConsumptionLog[]
}

model Session {
  id              String   @id @default(cuid())
  productId       String
  product         Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  amount          Float    @default(0)
  people          Int      @default(1)
  hitsCount       Int      @default(0)
  notes           String?
  bowlsPerPerson  Float    @default(0)
  personHits      String   @default("")
  rotationEnabled Boolean  @default(false)
  date            DateTime @default(now())
  createdAt       DateTime @default(now())

  consumptionLogs ConsumptionLog[]
}

model ConsumptionLog {
  id          String   @id @default(cuid())
  productId   String
  product     Product  @relation(fields: [productId], references: [id], onDelete: Cascade)
  sessionId   String?
  session     Session? @relation(fields: [sessionId], references: [id], onDelete: SetNull)
  amount      Float
  consumedAt  DateTime @default(now())
  type        String   @default("consume")
  note        String?
  createdAt   DateTime @default(now())
}

model ActivityLog {
  id         String   @id @default(cuid())
  type       String
  entityId   String
  entityType String
  details    String   @default("{}")
  productName String  @default("")
  createdAt  DateTime @default(now())
}

model AppSettings {
  id                String  @id @default("app")
  language          String  @default("en")
  theme             String  @default("dark")
  onboardingDone    Boolean @default(false)
  currency          String  @default("$")
  decimalPrecision  Int     @default(2)
  showTimerMs       Boolean @default(false)
  pinEnabled        Boolean @default(false)
  pinHash           String  @default("")
  lowStockThreshold Float   @default(3)
  statsVisibility   String  @default("{\"totalProducts\":true,\"totalAmount\":true,\"totalSessions\":true,\"averageRating\":true,\"averageTHC\":true,\"totalValue\":true,\"lastConsumed\":true}")
  sessionDefaults   String  @default("{\"defaultAmount\":0.5,\"defaultPeople\":2,\"defaultHitTimer\":10,\"defaultGramsPerBowl\":0.25,\"rotationEnabled\":false}")
  favoriteBrands    String  @default("[]")
  recentBrands      String  @default("[]")
  budgetLimit       Float   @default(0)
  budgetPeriod      String  @default("monthly")
}
HEREDOC_EOF

