  statsVisibility: {
    totalProducts: true,
    totalAmount: true,
    totalSessions: true,
    averageRating: true,
    averageTHC: true,
    totalValue: true,
    lastConsumed: true,
  },
  sessionDefaults: {
    defaultAmount: 0.5,
    defaultPeople: 2,
    defaultHitTimer: 10,
    defaultGramsPerBowl: 0.25,
    rotationEnabled: false,
  },
  favoriteBrands: [],
  recentBrands: [],
  budgetLimit: 0,
  budgetPeriod: 'monthly',
}

interface UIState {
  activeTab: 'inventory' | 'dashboard' | 'history' | 'settings'
  searchQuery: string
  sortBy: string
  filterBy: string
  layout: 'grid' | 'list' | 'compact'
  pageSize: number
  addProductOpen: boolean
  editingProduct: Product | null
  consumingProduct: Product | null
  sellingProduct: Product | null
  sessionProduct: Product | null
  settingsOpen: boolean
  setActiveTab: (tab: UIState['activeTab']) => void
  setSearchQuery: (q: string) => void
  setSortBy: (s: string) => void
  setFilterBy: (f: string) => void
  setLayout: (l: UIState['layout']) => void
  setPageSize: (s: number) => void
  openAddProduct: () => void
  openEditProduct: (p: Product) => void
  openConsume: (p: Product) => void
  openSell: (p: Product) => void
  openSession: (p: Product) => void
  openSettings: () => void
  closeAllModals: () => void
}

interface SettingsState {
  settings: AppSettings
  setSettings: (s: AppSettings) => void
  updateSettings: (partial: Partial<AppSettings>) => void
  resetSettings: () => void
}

type StoreState = UIState & SettingsState

export const useStore = create<StoreState>((set) => ({
  activeTab: 'inventory',
  searchQuery: '',
  sortBy: 'newest',
  filterBy: 'all',
  layout: 'grid',
  pageSize: 20,
  addProductOpen: false,
  editingProduct: null,
  consumingProduct: null,
  sellingProduct: null,
  sessionProduct: null,
  settingsOpen: false,

  setActiveTab: (tab) => set({ activeTab: tab }),
  setSearchQuery: (q) => set({ searchQuery: q }),
  setSortBy: (s) => set({ sortBy: s }),
  setFilterBy: (f) => set({ filterBy: f }),
  setLayout: (l) => set({ layout: l }),
  setPageSize: (s) => set({ pageSize: s }),

  openAddProduct: () => set({ addProductOpen: true, editingProduct: null, consumingProduct: null, sellingProduct: null, sessionProduct: null, settingsOpen: false }),
  openEditProduct: (p) => set({ addProductOpen: false, editingProduct: p, consumingProduct: null, sellingProduct: null, sessionProduct: null, settingsOpen: false }),
  openConsume: (p) => set({ addProductOpen: false, editingProduct: null, consumingProduct: p, sellingProduct: null, sessionProduct: null, settingsOpen: false }),
  openSell: (p) => set({ addProductOpen: false, editingProduct: null, consumingProduct: null, sellingProduct: p, sessionProduct: null, settingsOpen: false }),
  openSession: (p) => set({ addProductOpen: false, editingProduct: null, consumingProduct: null, sellingProduct: null, sessionProduct: p, settingsOpen: false }),
  openSettings: () => set({ addProductOpen: false, editingProduct: null, consumingProduct: null, sellingProduct: null, sessionProduct: null, settingsOpen: true }),
  closeAllModals: () => set({ addProductOpen: false, editingProduct: null, consumingProduct: null, sellingProduct: null, sessionProduct: null, settingsOpen: false }),

  settings: defaultSettings,
  setSettings: (s) => set({ settings: s }),
  updateSettings: (partial) => set((state) => ({ settings: { ...state.settings, ...partial } })),
  resetSettings: () => set({ settings: defaultSettings }),
}))
