import { db } from '@/lib/db'
import { NextRequest, NextResponse } from 'next/server'

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url)
    const page = parseInt(searchParams.get('page') || '1', 10)
    const limit = parseInt(searchParams.get('limit') || '20', 10)
    const from = searchParams.get('from')
    const to = searchParams.get('to')
    const type = searchParams.get('type')
    const entityType = searchParams.get('entityType')
    const where: Record<string, unknown> = {}
    if (from || to) { const createdAt: Record<string, Date> = {}; if (from) createdAt.gte = new Date(from); if (to) createdAt.lte = new Date(to); where.createdAt = createdAt }
    if (type) where.type = type
    if (entityType) where.entityType = entityType
    const total = await db.activityLog.count({ where })
    const totalPages = Math.ceil(total / limit)
    const logs = await db.activityLog.findMany({ where, orderBy: { createdAt: 'desc' }, skip: (page - 1) * limit, take: limit })
    return NextResponse.json({ logs, total, page, totalPages })
  } catch (error) {
    console.error('Error fetching activity logs:', error)
    return NextResponse.json({ error: 'Failed to fetch activity logs' }, { status: 500 })
  }
}
